function addTransaction(address destination, uint value, bytes memory data) public notNull(destination) returns (uint transactionId) {
    transactionId = transactionCount;
    transactions[transactionId] = Transaction({ destination: destination, value: value, data: data, executed: false });
    transactionCount += 1;
    emit Submission(transactionId);
}

